"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { AlertCircle, Archive, ArrowDown, ArrowLeft, ArrowRight, ArrowUp, BookOpen, Check, ChevronLeft, ChevronRight, CircleStop, Clock3, Eye, FilePlus2, History, LoaderCircle, Pencil, Play, Plus, RefreshCw, RotateCcw, Save, Search, ShieldCheck, Sparkles, Trash2, X } from "lucide-react";
import { PedagogicalRenderer } from "@elima/revision-ui";
import { projectTeacherView, type PedagogicalBlock, type PedagogicalCorrection, type PedagogicalGenerationRequest, type PedagogicalResourceBundle } from "@elima/pedagogy";
import { useTeacherContext } from "../TeacherContext";
import { useToast } from "@/components/ui/Toast";
import { PedagogicalClientError, createPedagogicalApi } from "@/lib/pedagogy/client";
import { advanceGeneration, GENERATION_STEPS, generationIdempotencyKey, loadGenerationIds, rememberGenerationId, validateGenerationRequest } from "@/lib/pedagogy/generation-controller";
import { appendBlock, cloneBundle, createBasicBlock, moveBlock, removeBlock, replaceBlock, validateEditedBundle } from "@/lib/pedagogy/editor";
import type { EditorialState, GenerationJob, PedagogicalResourceSummary, PedagogicalVersion, ResourceDetail, ResourceType, Review } from "@/lib/pedagogy/types";

const api = typeof window === "undefined" ? null : createPedagogicalApi();
const TYPES: Array<{ value: ResourceType; label: string }> = [
  { value: "revision_sheet", label: "Fiche de révision" }, { value: "course", label: "Cours approfondi" },
  { value: "exercise_series", label: "Exercices corrigés" }, { value: "mixed_support", label: "Fiche + exercices" },
  { value: "assessment", label: "Évaluation" }, { value: "exam_subject", label: "Sujet type examen" },
];
const STATES: Record<EditorialState, string> = { draft: "Brouillon", in_review: "En vérification", changes_requested: "À corriger", validated: "Validé", published: "Publié", archived: "Archivé" };
const input = "w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm outline-none focus:border-[var(--primary)] focus:ring-2 focus:ring-emerald-100";
const primary = "inline-flex items-center justify-center gap-2 rounded-xl bg-[var(--primary)] px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-50";
const secondary = "inline-flex items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-semibold text-slate-700 hover:bg-slate-50 disabled:opacity-50";
const message = (error: unknown) => error instanceof PedagogicalClientError ? error.message : "Une erreur inattendue empêche cette action.";

function Badge({ state }: { state: EditorialState }) {
  const color = ["published", "validated"].includes(state) ? "bg-emerald-100 text-emerald-800" : state === "in_review" ? "bg-sky-100 text-sky-800" : state === "changes_requested" ? "bg-amber-100 text-amber-800" : "bg-slate-100 text-slate-700";
  return <span className={`rounded-full px-2.5 py-1 text-xs font-semibold ${color}`}>{STATES[state]}</span>;
}

function Empty({ icon, title, text, action }: { icon: React.ReactNode; title: string; text: string; action?: React.ReactNode }) {
  return <div className="grid min-h-64 place-items-center rounded-2xl border border-dashed border-slate-300 bg-white p-8 text-center"><div><div className="mx-auto grid size-12 place-items-center rounded-2xl bg-emerald-50 text-[var(--primary)]">{icon}</div><h3 className="mt-4 font-bold">{title}</h3><p className="mt-1 max-w-md text-sm text-slate-500">{text}</p>{action ? <div className="mt-4">{action}</div> : null}</div></div>;
}

function Library({ create, open }: { create: () => void; open: (id: string) => void }) {
  const { subjects, classes } = useTeacherContext();
  const [filters, setFilters] = useState({ search: "", subject: "", level: "", resourceType: "", state: "" });
  const [page, setPage] = useState(0); const [data, setData] = useState<{ items: PedagogicalResourceSummary[]; total: number }>({ items: [], total: 0 }); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const limit = 9;
  const load = useCallback(async () => { if (!api) return; setLoading(true); setError(""); try { setData(await api.listResources({ ...filters, limit, offset: page * limit })); } catch (caught) { setError(message(caught)); } finally { setLoading(false); } }, [filters, page]);
  useEffect(() => { const timer = setTimeout(() => void load(), 250); return () => clearTimeout(timer); }, [load]);
  const set = (key: keyof typeof filters, value: string) => { setFilters((current) => ({ ...current, [key]: value })); setPage(0); };
  async function archive(item: PedagogicalResourceSummary) { if (!api || !confirm(`Archiver « ${item.title} » ?`)) return; try { await api.archiveResource(item.id); await load(); } catch (caught) { setError(message(caught)); } }
  return <section className="space-y-4"><div className="flex flex-wrap justify-between gap-3"><div><h2 className="text-xl font-bold">Bibliothèque pédagogique</h2><p className="text-sm text-slate-500">Supports structurés, versions et états éditoriaux.</p></div><button className={primary} onClick={create}><Sparkles size={17} />Créer un support</button></div>
    <div className="grid gap-2 rounded-2xl border bg-white p-3 sm:grid-cols-2 xl:grid-cols-5"><label className="relative sm:col-span-2 xl:col-span-1"><Search size={16} className="absolute left-3 top-3 text-slate-400" /><input className={`${input} pl-9`} placeholder="Rechercher" value={filters.search} onChange={(e) => set("search", e.target.value)} /></label><select className={input} value={filters.subject} onChange={(e) => set("subject", e.target.value)}><option value="">Toutes les matières</option>{subjects.map((s) => <option key={s.id}>{s.name}</option>)}</select><select className={input} value={filters.level} onChange={(e) => set("level", e.target.value)}><option value="">Tous les niveaux</option>{[...new Set(classes.map((c) => c.level))].map((level) => <option key={level}>{level}</option>)}</select><select className={input} value={filters.resourceType} onChange={(e) => set("resourceType", e.target.value)}><option value="">Tous les formats</option>{TYPES.map((type) => <option key={type.value} value={type.value}>{type.label}</option>)}</select><select className={input} value={filters.state} onChange={(e) => set("state", e.target.value)}><option value="">Tous les statuts</option>{Object.entries(STATES).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></div>
    {error ? <p className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800">{error}</p> : null}
    {loading ? <div className="grid min-h-64 place-items-center rounded-2xl bg-white"><LoaderCircle className="animate-spin" /></div> : !data.items.length ? <Empty icon={<BookOpen />} title="Aucune ressource" text="Créez votre premier support ou modifiez les filtres." action={<button className={primary} onClick={create}><Plus size={16} />Créer</button>} /> : <div className="grid gap-4 lg:grid-cols-2 xl:grid-cols-3">{data.items.map((item) => <article key={item.id} className="flex min-h-64 flex-col rounded-2xl border bg-white p-5 shadow-sm"><div className="flex justify-between gap-2"><Badge state={item.state} /><span className="text-xs text-slate-400">{new Intl.DateTimeFormat("fr", { dateStyle: "medium" }).format(new Date(item.updatedAt))}</span></div><h3 className="mt-4 line-clamp-2 text-lg font-bold">{item.title}</h3><p className="mt-1 text-sm font-semibold text-[var(--primary)]">{item.subject} · {item.level}{item.searchMetadata?.series ? ` ${item.searchMetadata.series}` : ""}</p><p className="mt-2 line-clamp-2 text-sm text-slate-500">{item.chapter || "Chapitre non renseigné"}</p><dl className="mt-4 grid grid-cols-2 gap-2 text-xs"><div><dt className="text-slate-400">Type</dt><dd>{TYPES.find((x) => x.value === item.resourceType)?.label}</dd></div><div><dt className="text-slate-400">Auteur</dt><dd className="truncate">{item.authorName || "Enseignant"}</dd></div></dl><div className="mt-auto flex gap-2 pt-5"><button className={`${primary} flex-1`} onClick={() => open(item.id)}>{["draft", "changes_requested"].includes(item.state) ? <Pencil size={16} /> : <Eye size={16} />}{["draft", "changes_requested"].includes(item.state) ? "Reprendre" : "Ouvrir"}</button>{item.state !== "archived" ? <button className={secondary} aria-label="Archiver" onClick={() => void archive(item)}><Archive size={16} /></button> : null}</div></article>)}</div>}
    {data.total > limit ? <div className="flex justify-center gap-3"><button className={secondary} disabled={!page} onClick={() => setPage((p) => p - 1)}><ChevronLeft size={16} />Précédent</button><span className="py-2 text-sm text-slate-500">{page + 1} / {Math.ceil(data.total / limit)}</span><button className={secondary} disabled={(page + 1) * limit >= data.total} onClick={() => setPage((p) => p + 1)}>Suivant<ChevronRight size={16} /></button></div> : null}</section>;
}

type Draft = { subject: string; level: string; track: string; chapter: string; objectives: string; competencies: string; resourceType: ResourceType; difficulty: PedagogicalGenerationRequest["difficulty"]; exerciseCount: number; estimatedMinutes: number; detailLevel: PedagogicalGenerationRequest["detailLevel"]; totalPoints: string; teacherInstructions: string; preferredTopics: string; excludedTopics: string };
function Wizard({ started, close }: { started: (job: GenerationJob) => void; close: () => void }) {
  const ctx = useTeacherContext(); const subject = ctx.subjects.find((x) => x.id === ctx.selectedSubjectId)?.name ?? ""; const level = ctx.classes.find((x) => x.id === ctx.selectedClassId)?.level ?? "";
  const [step, setStep] = useState(0); const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const [draft, setDraft] = useState<Draft>({ subject, level, track: "", chapter: "", objectives: "Comprendre la notion\nSavoir l’appliquer", competencies: "Raisonner\nCommuniquer une démarche", resourceType: "mixed_support", difficulty: "progressive", exerciseCount: 8, estimatedMinutes: 60, detailLevel: "standard", totalPoints: "20", teacherInstructions: "", preferredTopics: "", excludedTopics: "" });
  const set = <K extends keyof Draft>(key: K, value: Draft[K]) => setDraft((current) => ({ ...current, [key]: value })); const split = (value: string) => value.split(/\n|,/).map((x) => x.trim()).filter(Boolean);
  const request = useMemo(() => ({ country: "Côte d’Ivoire", countryCode: "CI", educationSystem: "Système éducatif ivoirien", language: "fr", subject: draft.subject, level: draft.level, ...(draft.track ? { track: draft.track } : {}), chapter: draft.chapter, objectives: split(draft.objectives), competencies: split(draft.competencies), resourceType: draft.resourceType, difficulty: draft.difficulty, exerciseCount: draft.exerciseCount, estimatedMinutes: draft.estimatedMinutes, targetAudience: "student" as const, detailLevel: draft.detailLevel, ...(draft.totalPoints ? { totalPoints: Number(draft.totalPoints) } : {}), ...(draft.teacherInstructions.trim() ? { teacherInstructions: draft.teacherInstructions.trim() } : {}), preferredTopics: split(draft.preferredTopics), excludedTopics: split(draft.excludedTopics), contextualExamples: [], references: [] }), [draft]); const valid = validateGenerationRequest(request);
  async function submit() { if (!api || !valid.success) return; setBusy(true); setError(""); try { const job = await api.submitGeneration(valid.data, generationIdempotencyKey(valid.data)); rememberGenerationId(localStorage, job.id); started(job); } catch (caught) { setError(message(caught)); } finally { setBusy(false); } }
  return <section className="rounded-2xl border bg-white p-5 shadow-sm sm:p-7"><div className="flex justify-between"><div><p className="text-xs font-bold uppercase text-[var(--primary)]">Création guidée</p><h2 className="mt-1 text-xl font-bold">{["Contexte pédagogique", "Type de support", "Personnalisation", "Vérification et lancement"][step]}</h2></div><button className={secondary} onClick={close}><X size={17} /></button></div><div className="mt-5 grid grid-cols-4 gap-2">{[0,1,2,3].map((n) => <span key={n} className={`h-1.5 rounded ${n <= step ? "bg-[var(--primary)]" : "bg-slate-200"}`} />)}</div><div className="mt-6 min-h-80">
    {step === 0 ? <div className="grid gap-4 sm:grid-cols-2"><Field label="Matière"><select className={input} value={draft.subject} onChange={(e) => set("subject", e.target.value)}><option value="">Choisir</option>{ctx.subjects.map((s) => <option key={s.id}>{s.name}</option>)}</select></Field><Field label="Niveau"><input className={input} value={draft.level} onChange={(e) => set("level", e.target.value)} /></Field><Field label="Série"><input className={input} placeholder="Lorsque nécessaire" value={draft.track} onChange={(e) => set("track", e.target.value)} /></Field><Field label="Chapitre ou notion"><input className={input} maxLength={200} value={draft.chapter} onChange={(e) => set("chapter", e.target.value)} /></Field><Field label="Objectifs (un par ligne)" wide><textarea className={`${input} min-h-24`} value={draft.objectives} onChange={(e) => set("objectives", e.target.value)} /></Field><Field label="Compétences visées (une par ligne)" wide><textarea className={`${input} min-h-24`} value={draft.competencies} onChange={(e) => set("competencies", e.target.value)} /></Field></div> : null}
    {step === 1 ? <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{TYPES.map((type) => <button key={type.value} className={`rounded-2xl border p-5 text-left ${draft.resourceType === type.value ? "border-[var(--primary)] bg-emerald-50 ring-2 ring-emerald-100" : ""}`} onClick={() => set("resourceType", type.value)}><FilePlus2 className="text-[var(--primary)]" /><strong className="mt-3 block">{type.label}</strong><small className="text-slate-500">Format pris en charge par le backend.</small></button>)}</div> : null}
    {step === 2 ? <div className="grid gap-4 sm:grid-cols-2"><Field label="Difficulté"><select className={input} value={draft.difficulty} onChange={(e) => set("difficulty", e.target.value as Draft["difficulty"])}><option value="easy">Facile</option><option value="intermediate">Intermédiaire</option><option value="advanced">Avancé</option><option value="progressive">Progressive</option></select></Field><Field label="Niveau de détail"><select className={input} value={draft.detailLevel} onChange={(e) => set("detailLevel", e.target.value as Draft["detailLevel"])}><option value="concise">Concis</option><option value="standard">Standard</option><option value="detailed">Détaillé</option></select></Field><Field label="Exercices (0–20)"><input type="number" min={0} max={20} className={input} value={draft.exerciseCount} onChange={(e) => set("exerciseCount", Number(e.target.value))} /></Field><Field label="Durée (10–480 min)"><input type="number" min={10} max={480} className={input} value={draft.estimatedMinutes} onChange={(e) => set("estimatedMinutes", Number(e.target.value))} /></Field><Field label="Barème (max. 100)"><input type="number" min={1} max={100} className={input} value={draft.totalPoints} onChange={(e) => set("totalPoints", e.target.value)} /></Field><Field label="Notions à privilégier"><input className={input} value={draft.preferredTopics} onChange={(e) => set("preferredTopics", e.target.value)} /></Field><Field label="Notions à exclure"><input className={input} value={draft.excludedTopics} onChange={(e) => set("excludedTopics", e.target.value)} /></Field><Field label="Consignes complémentaires" wide><textarea maxLength={4000} className={`${input} min-h-24`} value={draft.teacherInstructions} onChange={(e) => set("teacherInstructions", e.target.value)} /></Field></div> : null}
    {step === 3 ? <div className="grid gap-4 lg:grid-cols-2"><div className="rounded-2xl bg-slate-50 p-5"><h3 className="font-bold">Demande</h3><dl className="mt-4 space-y-3 text-sm">{[["Matière", request.subject], ["Niveau", request.level], ["Chapitre", request.chapter], ["Format", TYPES.find((x) => x.value === request.resourceType)?.label], ["Exercices", String(request.exerciseCount)], ["Durée", `${request.estimatedMinutes} min`]].map(([a,b]) => <div key={a} className="flex justify-between gap-4"><dt className="text-slate-500">{a}</dt><dd className="text-right font-semibold">{b}</dd></div>)}</dl></div><div className="rounded-2xl border border-emerald-200 bg-emerald-50 p-5"><ShieldCheck className="text-emerald-700" /><h3 className="mt-3 font-bold">Brouillon privé</h3><p className="mt-2 text-sm">Le support devra être relu et validé explicitement. Aucune publication élève n’est automatique.</p>{!valid.success ? <p className="mt-4 rounded-lg bg-white p-3 text-sm text-red-700">Certains champs sont incomplets ou hors limites.</p> : null}</div></div> : null}</div>
    {error ? <p className="rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</p> : null}<div className="mt-6 flex justify-between"><button className={secondary} onClick={() => step ? setStep(step - 1) : close()}><ArrowLeft size={16} />{step ? "Retour" : "Annuler"}</button>{step < 3 ? <button className={primary} onClick={() => setStep(step + 1)}>Continuer<ArrowRight size={16} /></button> : <button className={primary} disabled={!valid.success || busy} onClick={() => void submit()}>{busy ? <LoaderCircle className="animate-spin" size={16} /> : <Sparkles size={16} />}Lancer</button>}</div></section>;
}
function Field({ label, wide, children }: { label: string; wide?: boolean; children: React.ReactNode }) { return <label className={`text-sm font-semibold ${wide ? "sm:col-span-2" : ""}`}>{label}<div className="mt-1">{children}</div></label>; }

function Tracker({ initial, open, close }: { initial: GenerationJob; open: (id: string) => void; close?: () => void }) {
  const [job, setJob] = useState(initial); const [error, setError] = useState(""); const [auto, setAuto] = useState(["queued", "running"].includes(initial.status)); const processing = useRef(false);
  useEffect(() => { if (!api || !auto || processing.current || !["queued", "running"].includes(job.status)) return; let active = true; const timer = setTimeout(async () => { processing.current = true; try { const next = await advanceGeneration(api, job.id); if (active) { setJob(next); if (!["queued", "running"].includes(next.status)) setAuto(false); } } catch (caught) { if (active) { setError(message(caught)); setAuto(false); } } finally { processing.current = false; } }, 1200); return () => { active = false; clearTimeout(timer); }; }, [auto, job]);
  async function action(value: "cancel" | "retry") { if (!api) return; try { const next = await api.generationAction(job.id, value); setJob(next); setAuto(value === "retry"); setError(""); } catch (caught) { setError(message(caught)); } }
  async function refresh() { if (!api) return; try { setJob(await api.generationStatus(job.id)); } catch (caught) { setError(message(caught)); } }
  const current = GENERATION_STEPS.findIndex((x) => x.id === job.currentStep);
  return <section className="rounded-2xl border bg-white p-5 shadow-sm sm:p-7"><div className="flex justify-between gap-3"><div><p className="text-xs font-bold uppercase text-[var(--primary)]">Génération</p><h2 className="text-xl font-bold">{job.request.chapter}</h2><p className="text-sm text-slate-500">{job.request.subject} · {job.request.level}</p></div><strong className="text-sm">{job.status === "succeeded" ? "Terminée" : job.status === "failed" ? "Échec" : job.status === "cancelled" ? "Annulée" : "En cours"}</strong></div><ol className="mt-6 space-y-3">{GENERATION_STEPS.map((item, index) => { const done = job.status === "succeeded" || index < current; const active = index === current && ["queued", "running"].includes(job.status); return <li key={item.id} className={`flex items-center gap-3 rounded-xl border p-3 ${active ? "border-sky-200 bg-sky-50" : "border-slate-100"}`}><span className={`grid size-8 place-items-center rounded-full ${done ? "bg-emerald-600 text-white" : active ? "bg-sky-600 text-white" : "bg-slate-100"}`}>{done ? <Check size={16} /> : active ? <LoaderCircle size={16} className={auto ? "animate-spin" : ""} /> : index + 1}</span><strong className="text-sm">{item.label}</strong></li>; })}</ol>{error || job.error?.message ? <p className="mt-4 rounded-xl bg-red-50 p-4 text-sm text-red-700">{error || job.error?.message}</p> : null}<div className="mt-5 flex flex-wrap gap-2">{["queued", "running"].includes(job.status) ? <><button className={primary} disabled={auto} onClick={() => setAuto(true)}><Play size={16} />Reprendre</button><button className={secondary} onClick={() => void action("cancel")}><CircleStop size={16} />Annuler</button></> : null}{job.status === "failed" && job.error?.retryable !== false && job.attempts < job.maxAttempts ? <button className={primary} onClick={() => void action("retry")}><RotateCcw size={16} />Relancer</button> : null}{job.status === "succeeded" && job.resultResourceId ? <button className={primary} onClick={() => open(job.resultResourceId!)}><Eye size={16} />Ouvrir le brouillon</button> : null}<button className={secondary} onClick={() => void refresh()}><RefreshCw size={16} />Actualiser</button>{close ? <button className={secondary} onClick={close}>Fermer</button> : null}</div><details className="mt-4 text-xs text-slate-400"><summary>Informations techniques</summary><p className="break-all">Job {job.id}</p></details></section>;
}

function CorrectionEditor({ bundle, correction, options, change }: { bundle: PedagogicalResourceBundle; correction: PedagogicalCorrection; options?: Array<{ id: string; labelMarkdown: string }>; change: (next: PedagogicalResourceBundle) => void }) {
  const update = (next: PedagogicalCorrection) => { const copy = cloneBundle(bundle); copy.secrets.corrections = copy.secrets.corrections.map((item) => item.questionId === next.questionId ? next : item); change(copy); };
  const answer = correction.answerKey;
  return <div className="space-y-2 rounded-xl border border-emerald-200 bg-emerald-50 p-3"><strong className="text-xs uppercase text-emerald-800">Corrigé privé</strong><textarea className={input} value={correction.correctionMarkdown} onChange={(e) => update({ ...correction, correctionMarkdown: e.target.value })} />
    {answer.kind === "single_choice" ? <select className={input} value={answer.optionId} onChange={(e) => update({ ...correction, answerKey: { ...answer, optionId: e.target.value } })}>{options?.map((option) => <option key={option.id} value={option.id}>{option.labelMarkdown}</option>)}</select> : null}
    {answer.kind === "multiple_choice" ? <div className="space-y-1">{options?.map((option) => <label key={option.id} className="flex gap-2 text-sm"><input type="checkbox" checked={answer.optionIds.includes(option.id)} onChange={(e) => update({ ...correction, answerKey: { ...answer, optionIds: e.target.checked ? [...answer.optionIds, option.id] : answer.optionIds.filter((id) => id !== option.id) } })} />{option.labelMarkdown}</label>)}</div> : null}
    {answer.kind === "boolean" ? <select className={input} value={String(answer.value)} onChange={(e) => update({ ...correction, answerKey: { kind: "boolean", value: e.target.value === "true" } })}><option value="true">Vrai</option><option value="false">Faux</option></select> : null}
    {answer.kind === "numeric" ? <input type="number" className={input} value={answer.value} onChange={(e) => update({ ...correction, answerKey: { ...answer, value: Number(e.target.value) } })} /> : null}
    {answer.kind === "fraction" ? <div className="grid grid-cols-2 gap-2"><input type="number" className={input} value={answer.numerator} onChange={(e) => update({ ...correction, answerKey: { ...answer, numerator: Number(e.target.value) } })} /><input type="number" className={input} value={answer.denominator} onChange={(e) => update({ ...correction, answerKey: { ...answer, denominator: Number(e.target.value) } })} /></div> : null}
    {answer.kind === "text" ? <textarea className={input} value={answer.expectedElements.join("\n")} onChange={(e) => update({ ...correction, answerKey: { ...answer, expectedElements: e.target.value.split("\n").filter(Boolean) } })} /> : null}
    {answer.kind === "steps" ? <><input className={input} value={answer.finalAnswer ?? ""} placeholder="Réponse finale" onChange={(e) => update({ ...correction, answerKey: { ...answer, finalAnswer: e.target.value || undefined } })} /><textarea className={input} value={answer.requiredSteps.join("\n")} onChange={(e) => update({ ...correction, answerKey: { ...answer, requiredSteps: e.target.value.split("\n").filter(Boolean) } })} /></> : null}
    {answer.kind === "scientific_analysis" ? <><textarea className={input} value={answer.expectedObservations.join("\n")} onChange={(e) => update({ ...correction, answerKey: { ...answer, expectedObservations: e.target.value.split("\n").filter(Boolean) } })} /><textarea className={input} value={answer.expectedInterpretation.join("\n")} onChange={(e) => update({ ...correction, answerKey: { ...answer, expectedInterpretation: e.target.value.split("\n").filter(Boolean) } })} /></> : null}
    <div className="space-y-2">{correction.solutionSteps.map((step) => <textarea key={step.id} className={input} value={step.markdown} onChange={(e) => update({ ...correction, solutionSteps: correction.solutionSteps.map((item) => item.id === step.id ? { ...item, markdown: e.target.value } : item) })} />)}</div>
    <div className="space-y-2">{correction.rubric.map((rubric) => <div key={rubric.id} className="grid grid-cols-[1fr_6rem] gap-2"><input className={input} value={rubric.criterion} onChange={(e) => update({ ...correction, rubric: correction.rubric.map((item) => item.id === rubric.id ? { ...item, criterion: e.target.value } : item) })} /><input type="number" min={0} className={input} value={rubric.points} onChange={(e) => update({ ...correction, rubric: correction.rubric.map((item) => item.id === rubric.id ? { ...item, points: Number(e.target.value) } : item) })} /></div>)}</div>
  </div>;
}

function EditorBlock({ bundle, block, change }: { bundle: PedagogicalResourceBundle; block: PedagogicalBlock; change: (next: PedagogicalResourceBundle) => void }) {
  const set = (next: PedagogicalBlock) => change(replaceBlock(bundle, next)); const correction = block.type === "question" ? bundle.secrets.corrections.find((x) => x.questionId === block.question.id) : undefined;
  return <div id={`editor-${block.id}`} className="rounded-xl border bg-white p-4"><div className="flex justify-between"><strong className="text-xs uppercase text-slate-500">{block.type.replaceAll("_", " ")}</strong><div><button className="p-2" onClick={() => change(moveBlock(bundle, block.id, -1))}><ArrowUp size={15} /></button><button className="p-2" onClick={() => change(moveBlock(bundle, block.id, 1))}><ArrowDown size={15} /></button><button className="p-2 text-red-600" onClick={() => change(removeBlock(bundle, block.id))}><Trash2 size={15} /></button></div></div><div className="mt-3 space-y-2">
    {block.type === "heading" ? <input className={input} value={block.text} onChange={(e) => set({ ...block, text: e.target.value })} /> : null}{block.type === "rich_text" ? <textarea className={`${input} min-h-28`} value={block.markdown} onChange={(e) => set({ ...block, markdown: e.target.value })} /> : null}{block.type === "definition" ? <><input className={input} value={block.term} onChange={(e) => set({ ...block, term: e.target.value })} /><textarea className={input} value={block.markdown} onChange={(e) => set({ ...block, markdown: e.target.value })} /></> : null}{block.type === "callout" ? <><input className={input} value={block.title ?? ""} onChange={(e) => set({ ...block, title: e.target.value || undefined })} /><textarea className={input} value={block.markdown} onChange={(e) => set({ ...block, markdown: e.target.value })} /></> : null}{block.type === "formula" ? <textarea className={`${input} font-mono`} value={block.latex} onChange={(e) => set({ ...block, latex: e.target.value })} /> : null}
    {block.type === "worked_example" ? <><input className={input} value={block.title} onChange={(e) => set({ ...block, title: e.target.value })} /><textarea className={input} value={block.promptMarkdown} onChange={(e) => set({ ...block, promptMarkdown: e.target.value })} />{block.steps.map((step) => <textarea key={step.id} className={input} value={step.markdown} onChange={(e) => set({ ...block, steps: block.steps.map((x) => x.id === step.id ? { ...x, markdown: e.target.value } : x) })} />)}</> : null}{block.type === "summary" ? block.items.map((item, i) => <textarea key={i} className={input} value={item} onChange={(e) => set({ ...block, items: block.items.map((x, j) => i === j ? e.target.value : x) })} />) : null}
    {block.type === "question" ? <><textarea className={input} value={block.question.promptMarkdown} onChange={(e) => set({ ...block, question: { ...block.question, promptMarkdown: e.target.value } })} /><input type="number" className={input} value={block.question.points} onChange={(e) => set({ ...block, question: { ...block.question, points: Number(e.target.value) } })} />{block.question.options?.map((option) => <input key={option.id} className={input} value={option.labelMarkdown} onChange={(e) => set({ ...block, question: { ...block.question, options: block.question.options?.map((x) => x.id === option.id ? { ...x, labelMarkdown: e.target.value } : x) } })} />)}{correction ? <CorrectionEditor bundle={bundle} correction={correction} options={block.question.options} change={change} /> : null}</> : null}
    {["image", "table", "chart", "diagram", "exercise_group", "guided_activity", "assessment", "document_analysis"].includes(block.type) ? <p className="rounded-lg bg-slate-50 p-3 text-sm text-slate-500">Bloc avancé conservé dans son schéma canonique et visible dans l’aperçu.</p> : null}</div></div>;
}

function Resource({ id, close }: { id: string; close: () => void }) {
  const teacher = useTeacherContext();
  const [publishOpen, setPublishOpen] = useState(false);
  const [selectedClasses, setSelectedClasses] = useState<string[]>(teacher.selectedClassId ? [teacher.selectedClassId] : []);
  const [publication, setPublication] = useState({ activityMode: "training" as "training" | "evaluation", correctionsPolicy: "teacher_only" as "teacher_only" | "after_due_date" | "after_submission" | "never", availableFrom: "", availableUntil: "", maxAttempts: "", revealAfterAttempts: "" });
  const { success } = useToast(); const [detail, setDetail] = useState<ResourceDetail | null>(null); const [publicDetail, setPublicDetail] = useState<ResourceDetail | null>(null); const [actorId, setActorId] = useState<string | null>(null); const [bundle, setBundle] = useState<PedagogicalResourceBundle | null>(null); const [versions, setVersions] = useState<PedagogicalVersion[]>([]); const [reviews, setReviews] = useState<Review[]>([]); const [tab, setTab] = useState<"preview" | "edit" | "versions" | "validation">("preview"); const [audience, setAudience] = useState<"student" | "teacher">("teacher"); const [dirty, setDirty] = useState(false); const [loading, setLoading] = useState(true); const [error, setError] = useState("");
  const load = useCallback(async () => { if (!api) return; setLoading(true); try { const [next, userId] = await Promise.all([api.getResource(id, true), api.currentUserId()]); setActorId(userId); setDetail(next); if (next.version?.view?.audience === "teacher") setBundle({ document: next.version.view.document, secrets: next.version.view.secrets }); const [history, review] = await Promise.all([api.listVersions(id), next.version ? api.listReviews(next.version.id) : Promise.resolve({ items: [] })]); setVersions(history.items); setReviews(review.items); setDirty(false); setError(""); } catch (caught) { setError(message(caught)); } finally { setLoading(false); } }, [id]); useEffect(() => { void load(); }, [load]); useEffect(() => { const handler = (e: BeforeUnloadEvent) => { if (dirty) e.preventDefault(); }; addEventListener("beforeunload", handler); return () => removeEventListener("beforeunload", handler); }, [dirty]);
  const change = (next: PedagogicalResourceBundle) => { setBundle(next); setDirty(true); };
  async function student() { setAudience("student"); if (!publicDetail && api) try { setPublicDetail(await api.getResource(id, false)); } catch (caught) { setError(message(caught)); } }
  async function save() { if (!api || !bundle || !detail?.version) return; const parsed = validateEditedBundle(bundle); if (!parsed.success) return setError(`Document invalide : ${parsed.error.issues.length} champ(s) à corriger.`); try { const result = await api.updateResource(id, detail.version.id, detail.version.lockVersion, parsed.data); setDetail((d) => d ? { ...d, version: d.version ? { ...d.version, lockVersion: result.version.lockVersion } : null } : d); setDirty(false); success("Ressource enregistrée"); } catch (caught) { setError(caught instanceof PedagogicalClientError && caught.code === "pedagogical_version_conflict" ? "Conflit de modification : rechargez la version avant de reprendre." : message(caught)); } }
  async function workflow(action: "version" | "submit" | "validate" | "approve" | "reject" | "publish") { if (!api || !detail?.version) return; if (action === "publish") { setPublishOpen(true); return; } try { if (action === "version") await api.createVersion(id); if (action === "submit") await api.submitReview(detail.version.id); if (action === "validate") await api.runValidation(detail.version.id); if (action === "approve" || action === "reject") await api.decideReview(detail.version.id, action === "approve" ? "approve" : "reject", action === "reject" ? [prompt("Motif") || "Corrections demandées"] : []); await load(); } catch (caught) { setError(message(caught)); } }
  async function publishToRevision() { if (!api || !detail?.version || !selectedClasses.length) return; try { const options = { activityMode: publication.activityMode, correctionsPolicy: publication.correctionsPolicy, ...(publication.availableFrom ? { availableFrom: new Date(publication.availableFrom).toISOString() } : {}), ...(publication.availableUntil ? { availableUntil: new Date(publication.availableUntil).toISOString() } : {}), ...(publication.maxAttempts ? { maxAttempts: Number(publication.maxAttempts) } : {}), ...(publication.revealAfterAttempts ? { revealAfterAttempts: Number(publication.revealAfterAttempts) } : {}) }; const created = await api.publishVersion(detail.version.id, options); await Promise.all(selectedClasses.map((classId) => api.assignPublication(created.id, classId, options))); setPublishOpen(false); success(`Support publié pour ${selectedClasses.length} classe(s)`); await load(); } catch (caught) { setError(message(caught)); } }
  async function old(versionId: string) { if (!api) return; try { const next = await api.getVersion(versionId, true); setDetail(next); if (next.version?.view?.audience === "teacher") setBundle({ document: next.version.view.document, secrets: next.version.view.secrets }); setTab("preview"); } catch (caught) { setError(message(caught)); } }
  if (loading) return <div className="grid min-h-96 place-items-center"><LoaderCircle className="animate-spin" /></div>; if (!detail?.version || !bundle) return <Empty icon={<AlertCircle />} title="Ressource indisponible" text={error || "Ressource introuvable ou accès refusé."} action={<button className={secondary} onClick={close}>Retour</button>} />;
  if (publishOpen) return <section className="rounded-2xl border border-emerald-200 bg-emerald-50 p-5 sm:p-7"><div className="flex justify-between gap-4"><div><p className="text-xs font-bold uppercase text-emerald-700">Elima Révision</p><h2 className="mt-1 text-xl font-bold">Publier et affecter la version {detail.version.versionNumber}</h2><p className="mt-1 text-sm text-slate-600">Le contenu validé est figé. Les tentatives resteront liées à cette version exacte.</p></div><button className={secondary} onClick={() => setPublishOpen(false)}><X size={16} />Fermer</button></div><div className="mt-6 grid gap-4 md:grid-cols-2"><Field label="Mode"><select className={input} value={publication.activityMode} onChange={(e) => setPublication((value) => ({ ...value, activityMode: e.target.value as typeof value.activityMode }))}><option value="training">Entraînement</option><option value="evaluation">Évaluation</option></select></Field><Field label="Politique du corrigé"><select className={input} value={publication.correctionsPolicy} onChange={(e) => setPublication((value) => ({ ...value, correctionsPolicy: e.target.value as typeof value.correctionsPolicy }))}><option value="teacher_only">Enseignant uniquement</option><option value="after_submission">Après remise / essais</option><option value="after_due_date">Après l’échéance</option><option value="never">Jamais</option></select></Field><Field label="Disponible à partir du"><input type="datetime-local" className={input} value={publication.availableFrom} onChange={(e) => setPublication((value) => ({ ...value, availableFrom: e.target.value }))} /></Field><Field label="Échéance"><input type="datetime-local" className={input} value={publication.availableUntil} onChange={(e) => setPublication((value) => ({ ...value, availableUntil: e.target.value }))} /></Field><Field label="Tentatives maximales"><input type="number" min={1} className={input} value={publication.maxAttempts} onChange={(e) => setPublication((value) => ({ ...value, maxAttempts: e.target.value }))} /></Field><Field label="Corrigé après N essais"><input type="number" min={1} className={input} value={publication.revealAfterAttempts} onChange={(e) => setPublication((value) => ({ ...value, revealAfterAttempts: e.target.value }))} /></Field></div><fieldset className="mt-6"><legend className="font-bold">Classes destinataires</legend><p className="text-sm text-slate-500">L’appartenance active de chaque élève sera revérifiée à l’accès.</p><div className="mt-3 grid gap-2 sm:grid-cols-2">{teacher.classes.map((item) => <label key={item.id} className="flex items-center gap-3 rounded-xl border bg-white p-3 text-sm"><input type="checkbox" checked={selectedClasses.includes(item.id)} onChange={(event) => setSelectedClasses((current) => event.target.checked ? [...new Set([...current, item.id])] : current.filter((classId) => classId !== item.id))} /><span><strong>{item.name}</strong><small className="block text-slate-500">{item.level}</small></span></label>)}</div></fieldset>{error ? <p className="mt-4 rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</p> : null}<div className="mt-6 flex justify-end"><button className={primary} disabled={!selectedClasses.length} onClick={() => void publishToRevision()}><Check size={16} />Publier dans Révision</button></div></section>;
  const editable = ["draft", "changes_requested"].includes(detail.version.state); const latest = reviews[0]; const issues = [...(latest?.errors ?? []), ...(latest?.warnings ?? [])]; const teacherView = projectTeacherView(bundle); const studentView = publicDetail?.version?.view?.audience === "student" ? publicDetail.version.view : null; const canDecide = Boolean(actorId && actorId !== detail.resource.createdByUserId); const locate = (path: string) => { const index = Number(path.match(/blocks\.(\d+)/)?.[1]); const block = bundle.document.blocks[index]; if (block) { setTab("edit"); setTimeout(() => document.getElementById(`editor-${block.id}`)?.scrollIntoView({ behavior: "smooth" }), 50); } };
  return <section className="space-y-4"><header className="rounded-2xl border bg-white p-4"><div className="flex flex-wrap justify-between gap-3"><div className="flex gap-3"><button className={secondary} onClick={() => !dirty || confirm("Quitter sans enregistrer ?") ? close() : null}><ArrowLeft size={16} /></button><div><h2 className="font-bold">{detail.resource.title}</h2><div className="mt-1 flex gap-2"><Badge state={detail.version.state} />{dirty ? <small className="text-amber-700">Non enregistré</small> : null}</div></div></div><div className="flex gap-2">{editable ? <><button className={primary} disabled={!dirty} onClick={() => void save()}><Save size={16} />Enregistrer</button><button className={secondary} onClick={() => void workflow("submit")}><ShieldCheck size={16} />Soumettre</button></> : <button className={secondary} onClick={() => void workflow("version")}><FilePlus2 size={16} />Nouvelle version</button>}{detail.version.state === "validated" ? <button className={primary} onClick={() => void workflow("publish")}><Check size={16} />Publier en interne</button> : null}</div></div><nav className="mt-4 flex gap-1 overflow-x-auto rounded-xl bg-slate-100 p-1">{([['preview','Aperçu',Eye],['edit','Édition',Pencil],['versions','Versions',History],['validation','Validation',ShieldCheck]] as const).map(([value,label,Icon]) => <button key={value} className={`flex items-center gap-2 rounded-lg px-3 py-2 text-sm font-semibold ${tab === value ? "bg-white shadow" : "text-slate-500"}`} onClick={() => setTab(value)}><Icon size={15} />{label}</button>)}</nav></header>{error ? <p className="rounded-xl bg-red-50 p-4 text-sm text-red-700">{error}</p> : null}
    {tab === "preview" ? <><div className="flex justify-center"><div className="rounded-xl border bg-white p-1"><button className={`rounded-lg px-4 py-2 text-sm font-semibold ${audience === "student" ? "bg-[var(--primary)] text-white" : ""}`} onClick={() => void student()}>Vue élève</button><button className={`rounded-lg px-4 py-2 text-sm font-semibold ${audience === "teacher" ? "bg-[var(--primary)] text-white" : ""}`} onClick={() => setAudience("teacher")}>Vue enseignant</button></div></div>{audience === "teacher" ? <PedagogicalRenderer view={teacherView} /> : studentView ? <PedagogicalRenderer view={studentView} /> : <div className="grid min-h-64 place-items-center rounded-2xl bg-white"><LoaderCircle className="animate-spin" /><span className="sr-only">Chargement de la projection élève</span></div>}</> : null}
    {tab === "edit" ? <div className="grid gap-5 xl:grid-cols-2"><div className="space-y-4"><div className="rounded-xl border bg-white p-4"><input className={input} value={bundle.document.metadata.title} onChange={(e) => { const copy = cloneBundle(bundle); copy.document.metadata.title = e.target.value; change(copy); }} /><textarea className={`${input} mt-2`} value={bundle.document.metadata.description} onChange={(e) => { const copy = cloneBundle(bundle); copy.document.metadata.description = e.target.value; change(copy); }} /></div>{bundle.document.blocks.map((block) => <EditorBlock key={block.id} bundle={bundle} block={block} change={change} />)}<div className="rounded-xl border border-dashed bg-white p-4"><strong>Ajouter un bloc</strong><div className="mt-3 flex flex-wrap gap-2">{(["heading","rich_text","definition","callout","formula","summary"] as const).map((type) => <button key={type} className={secondary} onClick={() => change(appendBlock(bundle, createBasicBlock(type)))}><Plus size={14} />{type}</button>)}</div></div></div><div className="xl:sticky xl:top-5 xl:h-[calc(100vh-2.5rem)] xl:overflow-auto"><PedagogicalRenderer view={projectTeacherView(bundle)} /></div></div> : null}
    {tab === "versions" ? <div className="rounded-2xl border bg-white p-5"><h3 className="font-bold">Historique des versions</h3>{versions.map((version) => <div key={version.id} className="flex items-center justify-between border-b py-4"><div><strong>Version {version.versionNumber}</strong><p className="text-xs text-slate-500">{new Date(version.updatedAt).toLocaleString("fr")}</p></div><div className="flex gap-2"><Badge state={version.state} /><button className={secondary} onClick={() => void old(version.id)}><Eye size={15} />Consulter</button></div></div>)}</div> : null}
    {tab === "validation" ? <div className="rounded-2xl border bg-white p-5"><div className="flex justify-between"><div><h3 className="font-bold">Vérification pédagogique</h3><p className="text-xs text-slate-500">Automatique puis décision humaine explicite</p></div><button className={secondary} disabled={detail.version.state !== "in_review"} onClick={() => void workflow("validate")}><ShieldCheck size={15} />Vérifier</button></div><div className="mt-4 grid grid-cols-3 gap-2 text-center text-xs"><div className="rounded-lg bg-red-50 p-2"><strong className="block text-lg">{latest?.errors?.length ?? 0}</strong>Erreurs</div><div className="rounded-lg bg-amber-50 p-2"><strong className="block text-lg">{latest?.warnings?.length ?? 0}</strong>Avertissements</div><div className="rounded-lg bg-sky-50 p-2"><strong className="block text-lg">{latest?.result === "passed" ? 1 : 0}</strong>Réussi</div></div><div className="mt-3 space-y-2">{issues.map((issue, i) => <button key={`${issue.code}-${i}`} className="w-full rounded-lg border p-3 text-left text-sm" onClick={() => locate(issue.path)}>{issue.message}<small className="block text-slate-400">{issue.code}</small></button>)}</div>{detail.version.state === "in_review" && latest?.result === "passed" && canDecide ? <div className="mt-4 flex gap-2"><button className={primary} onClick={() => void workflow("approve")}><Check size={15} />Approuver</button><button className={secondary} onClick={() => void workflow("reject")}><RotateCcw size={15} />À corriger</button></div> : detail.version.state === "in_review" && latest?.result === "passed" ? <p className="mt-4 rounded-lg bg-slate-50 p-3 text-sm text-slate-600">La décision humaine doit être prise par un autre réviseur autorisé.</p> : null}</div> : null}</section>;
}

function PublicationTracking() {
  const [publications, setPublications] = useState<Array<{ id: string; state: string; activity_mode: string; published_at: string; available_until?: string; pedagogical_assignments?: Array<{ id: string }> }>>([]); const [selected, setSelected] = useState<string | null>(null); const [tracking, setTracking] = useState<{ learners: number; started: number; submitted: number; pendingReview: number } | null>(null); const [error, setError] = useState("");
  const load = useCallback(async () => { if (!api) return; try { setPublications((await api.listPublications()).items); } catch (caught) { setError(message(caught)); } }, []);
  useEffect(() => { void load(); }, [load]);
  async function inspect(id: string) { if (!api) return; setSelected(id); try { setTracking((await api.publicationTracking(id)).summary); setError(""); } catch (caught) { setError(message(caught)); } }
  async function withdraw(id: string) { if (!api || !confirm("Retirer ce support de Révision ? Les tentatives existantes seront conservées.")) return; try { await api.withdrawPublication(id, "Retrait manuel depuis l’atelier enseignant"); await load(); if (selected === id) setTracking(null); } catch (caught) { setError(message(caught)); } }
  return <section className="space-y-4"><div><h2 className="text-xl font-bold">Suivi des publications Révision</h2><p className="text-sm text-slate-500">Progression, remises et réponses qui attendent une validation humaine.</p></div>{error ? <p className="rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</p> : null}{tracking ? <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">{[["Élèves",tracking.learners],["Tentatives",tracking.started],["Remises",tracking.submitted],["À valider",tracking.pendingReview]].map(([label,value]) => <div key={label} className="rounded-2xl border bg-white p-4"><strong className="text-2xl text-[var(--primary)]">{value}</strong><p className="text-sm text-slate-500">{label}</p></div>)}</div> : null}<div className="space-y-3">{publications.map((item) => <article key={item.id} className="flex flex-wrap items-center justify-between gap-3 rounded-2xl border bg-white p-4"><div><div className="flex gap-2"><strong>Publication {item.id.slice(0, 8)}</strong><span className="rounded-full bg-slate-100 px-2 py-0.5 text-xs">{item.state}</span></div><p className="mt-1 text-xs text-slate-500">{item.activity_mode === "evaluation" ? "Évaluation" : "Entraînement"} · {item.pedagogical_assignments?.length ?? 0} affectation(s) · {new Date(item.published_at).toLocaleDateString("fr")}</p></div><div className="flex gap-2"><button className={secondary} onClick={() => void inspect(item.id)}><Eye size={15} />Suivre</button>{item.state !== "withdrawn" ? <button className={secondary} onClick={() => void withdraw(item.id)}><CircleStop size={15} />Retirer</button> : null}</div></article>)}</div>{!publications.length ? <Empty icon={<History />} title="Aucune publication Révision" text="Les supports validés et affectés apparaîtront ici." /> : null}</section>;
}

function PdfExports() {
  const [items, setItems] = useState<PedagogicalResourceSummary[]>([]); const [busy, setBusy] = useState(""); const [error, setError] = useState("");
  useEffect(() => { if (!api) return; void api.listResources({ limit: 100, offset: 0 }).then((page) => setItems(page.items)).catch((caught) => setError(message(caught))); }, []);
  async function preview(item: PedagogicalResourceSummary, audience: "student" | "teacher") { if (!api || !item.currentVersionId) return; const key = `${item.id}-${audience}`; setBusy(key); setError(""); const popup = window.open("", "_blank"); try { const result = await api.exportPdf(item.currentVersionId, audience); const bytes = Uint8Array.from(atob(result.contentBase64), (character) => character.charCodeAt(0)); const url = URL.createObjectURL(new Blob([bytes], { type: result.mimeType })); if (popup) popup.location.href = url; else { const anchor = document.createElement("a"); anchor.href = url; anchor.download = result.fileName; anchor.click(); } window.setTimeout(() => URL.revokeObjectURL(url), 60_000); } catch (caught) { popup?.close(); setError(message(caught)); } finally { setBusy(""); } }
  return <section className="space-y-4"><div><h2 className="text-xl font-bold">Exports PDF pédagogiques</h2><p className="text-sm text-slate-500">Prévisualisez une version élève sans corrigé ou la version enseignant complète.</p></div>{error ? <p className="rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</p> : null}<div className="grid gap-3 lg:grid-cols-2">{items.map((item) => <article key={item.id} className="rounded-2xl border bg-white p-5"><div className="flex justify-between gap-3"><div><h3 className="font-bold">{item.title}</h3><p className="text-xs text-slate-500">{item.subject} · {item.level} · version courante</p></div><Badge state={item.state} /></div><div className="mt-4 flex flex-wrap gap-2"><button className={secondary} disabled={!item.currentVersionId || busy === `${item.id}-student`} onClick={() => void preview(item, "student")}><Eye size={15} />PDF élève</button><button className={primary} disabled={!item.currentVersionId || busy === `${item.id}-teacher`} onClick={() => void preview(item, "teacher")}><ShieldCheck size={15} />PDF enseignant</button></div></article>)}</div>{!items.length ? <Empty icon={<BookOpen />} title="Aucun support exportable" text="Créez une ressource pédagogique avant de générer ses PDF." /> : null}</section>;
}

function ScientificContentEditor() {
  const { success } = useToast(); const [resources, setResources] = useState<PedagogicalResourceSummary[]>([]); const [detail, setDetail] = useState<ResourceDetail | null>(null); const [bundle, setBundle] = useState<PedagogicalResourceBundle | null>(null); const [error, setError] = useState(""); const scientific = (bundle?.document.blocks.filter((block) => ["table", "chart", "diagram", "image"].includes(block.type)) ?? []) as Array<Extract<PedagogicalBlock, { type: "table" | "chart" | "diagram" | "image" }> & { alt?: string }>;
  useEffect(() => { if (!api) return; void api.listResources({ limit: 100, offset: 0 }).then((page) => setResources(page.items)).catch((caught) => setError(message(caught))); }, []);
  async function open(resourceId: string) { if (!api) return; try { const next = await api.getResource(resourceId, true); setDetail(next); if (next.version?.view?.audience === "teacher") setBundle({ document: next.version.view.document, secrets: next.version.view.secrets }); setError(""); } catch (caught) { setError(message(caught)); } }
  function replace(next: PedagogicalBlock) { if (!bundle) return; setBundle(replaceBlock(bundle, next)); }
  async function saveScientific() { if (!api || !detail?.version || !bundle) return; const checked = validateEditedBundle(bundle); if (!checked.success) return setError(`Contenu invalide : ${checked.error.issues.length} champ(s) à corriger.`); try { const result = await api.updateResource(detail.resource.id, detail.version.id, detail.version.lockVersion, checked.data); setDetail((current) => current ? { ...current, version: current.version ? { ...current.version, lockVersion: result.version.lockVersion } : null } : current); success("Contenus scientifiques enregistrés"); } catch (caught) { setError(message(caught)); } }
  if (!bundle) return <section className="space-y-4"><div><h2 className="text-xl font-bold">Contenus scientifiques</h2><p className="text-sm text-slate-500">Choisissez un brouillon pour modifier ses données déclaratives, sans HTML ni script.</p></div>{error ? <p className="rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</p> : null}<div className="grid gap-3 lg:grid-cols-2">{resources.map((item) => <button key={item.id} className="rounded-2xl border bg-white p-5 text-left" onClick={() => void open(item.id)}><strong>{item.title}</strong><span className="mt-1 block text-xs text-slate-500">{item.subject} · {item.level} · {STATES[item.state]}</span></button>)}</div></section>;
  return <section className="space-y-4"><div className="flex flex-wrap justify-between gap-3"><div><button className="text-sm font-semibold text-[var(--primary)]" onClick={() => { setBundle(null); setDetail(null); }}>← Autres supports</button><h2 className="mt-2 text-xl font-bold">Données scientifiques · {detail?.resource.title}</h2><p className="text-sm text-slate-500">Les références et avertissements restent visibles dans l’aperçu partagé.</p></div><button className={primary} disabled={!detail?.version || !["draft", "changes_requested"].includes(detail.version.state)} onClick={() => void saveScientific()}><Save size={16} />Enregistrer</button></div>{error ? <p className="rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</p> : null}<div className="space-y-4">{scientific.map((block) => <article key={block.id} className="rounded-2xl border bg-white p-5"><div className="flex justify-between"><strong>{block.type} · {"title" in block ? block.title : block.alt}</strong><small className="text-slate-400">{block.id}</small></div><div className="mt-4 space-y-3">{block.type === "chart" ? <><input className={input} value={block.title} onChange={(e) => replace({ ...block, title: e.target.value })} /><div className="grid gap-2 sm:grid-cols-2"><input className={input} value={block.xAxis.label} onChange={(e) => replace({ ...block, xAxis: { ...block.xAxis, label: e.target.value } })} /><input className={input} value={block.yAxis.label} onChange={(e) => replace({ ...block, yAxis: { ...block.yAxis, label: e.target.value } })} /></div><label className="text-xs font-semibold">Valeurs de l’axe X, séparées par des virgules<input className={`${input} mt-1`} value={block.xAxis.values.join(", ")} onChange={(e) => replace({ ...block, xAxis: { ...block.xAxis, values: e.target.value.split(",").map((value) => value.trim()).filter(Boolean).map((value) => Number.isFinite(Number(value)) ? Number(value) : value) } })} /></label>{block.series.map((series) => <label key={series.id} className="block text-xs font-semibold">{series.label}<input className={`${input} mt-1`} value={series.values.join(", ")} onChange={(e) => replace({ ...block, series: block.series.map((item) => item.id === series.id ? { ...item, values: e.target.value.split(",").map(Number).filter(Number.isFinite) } : item) })} /></label>)}<textarea className={input} value={block.caption ?? ""} placeholder="Légende et nature des données" onChange={(e) => replace({ ...block, caption: e.target.value || undefined })} /></> : null}{block.type === "table" ? <><input className={input} value={block.title ?? ""} onChange={(e) => replace({ ...block, title: e.target.value || undefined })} />{block.rows.map((row) => <div key={row.id} className="grid gap-2" style={{ gridTemplateColumns: `repeat(${block.columns.length}, minmax(0, 1fr))` }}>{row.cells.map((cell, index) => <input key={index} className={input} value={String(cell ?? "")} onChange={(e) => replace({ ...block, rows: block.rows.map((item) => item.id === row.id ? { ...item, cells: item.cells.map((value, cellIndex) => cellIndex === index ? e.target.value : value) } : item) })} />)}</div>)}<textarea className={input} value={block.caption ?? ""} placeholder="Note, protocole ou source" onChange={(e) => replace({ ...block, caption: e.target.value || undefined })} /></> : null}{block.type === "diagram" ? <><input className={input} value={block.title} onChange={(e) => replace({ ...block, title: e.target.value })} /><textarea className={input} value={block.descriptionMarkdown} onChange={(e) => replace({ ...block, descriptionMarkdown: e.target.value })} />{block.nodes.map((node) => <div key={node.id} className="grid gap-2 sm:grid-cols-2"><input className={input} value={node.label} onChange={(e) => replace({ ...block, nodes: block.nodes.map((item) => item.id === node.id ? { ...item, label: e.target.value } : item) })} /><input className={input} value={node.description ?? ""} placeholder="Annotation" onChange={(e) => replace({ ...block, nodes: block.nodes.map((item) => item.id === node.id ? { ...item, description: e.target.value || undefined } : item) })} /></div>)}<textarea className={input} value={block.caption ?? ""} placeholder="Légende" onChange={(e) => replace({ ...block, caption: e.target.value || undefined })} /></> : null}{block.type === "image" ? <><input className={input} value={block.alt} onChange={(e) => replace({ ...block, alt: e.target.value })} /><input className={input} value={block.uri ?? ""} placeholder="URI HTTPS ou asset privé autorisé" onChange={(e) => replace({ ...block, uri: e.target.value || undefined })} /><textarea className={input} value={block.caption ?? ""} placeholder="Légende et droits" onChange={(e) => replace({ ...block, caption: e.target.value || undefined })} />{!block.uri ? <p className="rounded-xl bg-amber-50 p-3 text-sm text-amber-800">Asset absent : le brouillon peut être conservé mais ne doit pas être présenté comme une illustration disponible.</p> : null}</> : null}</div></article>)}</div>{!scientific.length ? <Empty icon={<AlertCircle />} title="Aucun bloc scientifique" text="Ce support ne contient actuellement ni tableau, ni graphique, ni schéma, ni image." /> : null}</section>;
}

export function PedagogyWorkshop() {
  const [view, setView] = useState<"library" | "create" | "jobs" | "tracking" | "exports" | "science" | "resource">("library"); const [resource, setResource] = useState<string | null>(null); const [job, setJob] = useState<GenerationJob | null>(null); const [jobs, setJobs] = useState<GenerationJob[]>([]);
  const open = (id: string) => { setResource(id); setView("resource"); }; useEffect(() => { if (view !== "jobs" || !api) return; void Promise.allSettled(loadGenerationIds(localStorage).map((id) => api.generationStatus(id))).then((items) => setJobs(items.flatMap((item) => item.status === "fulfilled" ? [item.value] : []))); }, [view]);
  if (view === "resource" && resource) return <Resource id={resource} close={() => { setResource(null); setView("library"); }} />;
  return <div className="space-y-5"><nav className="flex gap-1 overflow-x-auto rounded-2xl border bg-white p-1.5">{([['library','Bibliothèque',BookOpen],['create','Créer',Sparkles],['jobs','Générations',Clock3],['science','Sciences',Pencil],['tracking','Suivi Révision',History],['exports','Exports PDF',Eye]] as const).map(([value,label,Icon]) => <button key={value} onClick={() => setView(value)} className={`flex items-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold ${view === value ? "bg-[var(--primary)] text-white" : "text-slate-600"}`}><Icon size={16} />{label}</button>)}</nav>{view === "library" ? <Library create={() => setView("create")} open={open} /> : null}{view === "create" ? job ? <Tracker initial={job} open={open} close={() => { setJob(null); setView("library"); }} /> : <Wizard started={setJob} close={() => setView("library")} /> : null}{view === "jobs" ? <section className="space-y-4"><h2 className="text-xl font-bold">Générations récentes</h2>{jobs.length ? jobs.map((item) => <Tracker key={`${item.id}-${item.updatedAt}`} initial={item} open={open} />) : <Empty icon={<Clock3 />} title="Aucune génération retrouvée" text="Les traitements seront conservés ici pour permettre leur reprise." />}</section> : null}{view === "science" ? <ScientificContentEditor /> : null}{view === "tracking" ? <PublicationTracking /> : null}{view === "exports" ? <PdfExports /> : null}</div>;
}
